			// for the contract. We wrap with a short "pre-push:" prefix
			// so the user sees the source of the abort without losing
			// the underlying type (errors.As still finds the sentinels).
			if hookErr == nil {
				return nil
			}
			return fmt.Errorf("pre-push: %w", hookErr)
		},
	}
}

